package kiro

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// Kiro IDE session store, v2 layout.
//
// Newer Kiro IDE builds no longer write chats to
// globalStorage/kiro.kiroagent/workspace-sessions/<base64(cwd)>/<id>.json.
// They write one directory per chat under the user's ~/.kiro instead:
//
//	~/.kiro/sessions/<hex(sha256(cwd))[:16]>/sess_<uuid>/messages.jsonl
//	~/.kiro/sessions/<hex(sha256(cwd))[:16]>/sess_<uuid>/session.json
//
// messages.jsonl is append-only, one event per line:
//
//	{"id":"…","timestamp":"RFC3339","payload":{"type":"user","content":"…"}}
//
// with payload types user, assistant, tool_call (toolName + args),
// tool_result, turn_start/turn_end and several metadata types this adapter
// ignores. Unlike the legacy store, the v2 transcript already carries the
// real assistant text and every tool call, so no execution-log or hook-side
// tool-call enrichment is needed.
//
// What breaks if this file is removed: on Kiro IDE builds that only write the
// v2 store, IDE hooks resolve no chat and every checkpoint gets a "{}"
// placeholder transcript.

const (
	ideV2SessionPrefix = "sess_"
	ideV2MessagesFile  = "messages.jsonl"
	ideV2RepoHashLen   = 16
)

// ideV2WorkspaceDir returns the per-workspace directory Kiro IDE uses for v2
// chats. The directory name is the first 16 hex characters of the SHA-256 of
// the workspace path, as observed on Linux Kiro IDE builds.
func ideV2WorkspaceDir(cwd string) (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve home dir: %w", err)
	}
	sum := sha256.Sum256([]byte(filepath.Clean(cwd)))
	return filepath.Join(home, ".kiro", "sessions", hex.EncodeToString(sum[:])[:ideV2RepoHashLen]), nil
}

// isIDEV2SessionID reports whether id has the v2 chat ID shape and is safe to
// use as a single path segment.
func isIDEV2SessionID(id string) bool {
	return strings.HasPrefix(id, ideV2SessionPrefix) && len(id) > len(ideV2SessionPrefix) && filepath.IsLocal(id) && !strings.ContainsAny(id, `/\`)
}

// ideV2MessagesPath returns the transcript path for a v2 chat and whether it
// exists.
func ideV2MessagesPath(cwd, sessionID string) (string, bool) {
	if !isIDEV2SessionID(sessionID) {
		return "", false
	}
	dir, err := ideV2WorkspaceDir(cwd)
	if err != nil {
		return "", false
	}
	path := filepath.Join(dir, sessionID, ideV2MessagesFile)
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return "", false
	}
	return path, true
}

// mostRecentlyActiveIDEV2SessionID returns the v2 chat whose messages.jsonl was
// modified most recently. Kiro appends the prompt to the active chat before it
// fires promptSubmit, so mtime identifies the chat that fired the hook. This
// mirrors mostRecentlyActiveIDESessionID for the legacy store.
func mostRecentlyActiveIDEV2SessionID(cwd string) (string, error) {
	dir, err := ideV2WorkspaceDir(cwd)
	if err != nil {
		return "", err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return "", fmt.Errorf("read IDE v2 sessions dir: %w", err)
	}
	var bestID string
	var bestMtime time.Time
	for _, entry := range entries {
		if !entry.IsDir() || !isIDEV2SessionID(entry.Name()) {
			continue
		}
		info, err := os.Stat(filepath.Join(dir, entry.Name(), ideV2MessagesFile))
		if err != nil || info.IsDir() {
			continue
		}
		if bestID == "" || info.ModTime().After(bestMtime) {
			bestID = entry.Name()
			bestMtime = info.ModTime()
		}
	}
	if bestID == "" {
		return "", errors.New("no IDE v2 session transcripts found")
	}
	return bestID, nil
}

type ideV2Record struct {
	Timestamp string          `json:"timestamp"`
	Payload   json.RawMessage `json:"payload"`
}

type ideV2Payload struct {
	Type       string          `json:"type"`
	Content    json.RawMessage `json:"content"`
	ToolCallID string          `json:"toolCallId"`
	ToolName   string          `json:"toolName"`
	Args       json.RawMessage `json:"args"`
}

// convertIDEV2Messages turns a v2 messages.jsonl into the paired history shape
// the rest of this adapter works with. Order is preserved: each assistant
// message and each run of consecutive tool calls becomes its own history
// entry, and the first entry of a turn carries the user's prompt.
//
// Malformed lines are skipped rather than failing the whole capture: Kiro
// appends while hooks run, so the final line can be partially written.
func convertIDEV2Messages(data []byte) (*kiroTranscript, error) {
	t := &kiroTranscript{}

	var pendingPrompt string
	var pendingPromptTS string
	havePrompt := false
	var pendingCalls []kiroToolCall

	attachPrompt := func(entry *kiroHistoryEntry) error {
		if !havePrompt {
			return nil
		}
		content, err := json.Marshal(kiroPromptContent{
			Prompt: struct {
				Prompt string `json:"prompt"`
			}{Prompt: pendingPrompt},
		})
		if err != nil {
			return err
		}
		entry.User = kiroUserMessage{Content: content, Timestamp: pendingPromptTS}
		havePrompt = false
		pendingPrompt, pendingPromptTS = "", ""
		return nil
	}

	flushCalls := func() error {
		if len(pendingCalls) == 0 {
			return nil
		}
		raw, err := json.Marshal(kiroToolUseContent{ToolUse: kiroToolUsePayload{ToolUses: pendingCalls}})
		if err != nil {
			return err
		}
		entry := kiroHistoryEntry{Assistant: raw}
		if err := attachPrompt(&entry); err != nil {
			return err
		}
		t.History = append(t.History, entry)
		pendingCalls = nil
		return nil
	}

	flushPromptOnly := func() error {
		if !havePrompt {
			return nil
		}
		entry := kiroHistoryEntry{}
		if err := attachPrompt(&entry); err != nil {
			return err
		}
		t.History = append(t.History, entry)
		return nil
	}

	reader := bufio.NewReader(bytes.NewReader(data))
	for {
		line, readErr := reader.ReadBytes('\n')
		line = bytes.TrimSpace(line)
		if len(line) > 0 {
			var rec ideV2Record
			var payload ideV2Payload
			if json.Unmarshal(line, &rec) == nil && json.Unmarshal(rec.Payload, &payload) == nil {
				switch payload.Type {
				case "user":
					if err := flushCalls(); err != nil {
						return nil, err
					}
					// Two prompts with no reply between them: keep the first.
					if err := flushPromptOnly(); err != nil {
						return nil, err
					}
					var text string
					if json.Unmarshal(payload.Content, &text) == nil {
						pendingPrompt = text
						pendingPromptTS = rec.Timestamp
						havePrompt = true
					}
				case "assistant":
					var text string
					if json.Unmarshal(payload.Content, &text) != nil || strings.TrimSpace(text) == "" {
						continue
					}
					if err := flushCalls(); err != nil {
						return nil, err
					}
					raw, err := json.Marshal(kiroResponseContent{Response: kiroResponsePayload{Content: text}})
					if err != nil {
						return nil, err
					}
					entry := kiroHistoryEntry{Assistant: raw}
					if err := attachPrompt(&entry); err != nil {
						return nil, err
					}
					t.History = append(t.History, entry)
				case "tool_call":
					if payload.ToolName == "" {
						continue
					}
					pendingCalls = append(pendingCalls, kiroToolCall{
						ID:   payload.ToolCallID,
						Name: payload.ToolName,
						Args: payload.Args,
					})
				}
			}
		}
		if readErr != nil {
			if errors.Is(readErr, io.EOF) {
				break
			}
			return nil, readErr
		}
	}
	if err := flushCalls(); err != nil {
		return nil, err
	}
	if err := flushPromptOnly(); err != nil {
		return nil, err
	}
	return t, nil
}

// ensureIDEV2Transcript reads a v2 chat, converts it, and writes the trimmed
// JSONL cache Entire reads. It shares the trim/cache tail with the legacy
// IDE path.
func (a *Agent) ensureIDEV2Transcript(cwd, entireSessionID, ideSessionID, messagesPath string) (string, error) {
	raw, err := os.ReadFile(messagesPath)
	if err != nil {
		return "", fmt.Errorf("failed to read IDE v2 transcript %s: %w", messagesPath, err)
	}
	converted, err := convertIDEV2Messages(raw)
	if err != nil {
		return "", fmt.Errorf("failed to convert IDE v2 transcript: %w", err)
	}
	if len(converted.History) == 0 {
		return "", errors.New("IDE v2 transcript has no history entries")
	}
	// The v2 transcript already contains every tool call, so the hook-side
	// capture file would only duplicate them. Drain it so it cannot leak into
	// a later turn.
	_ = a.readAndClearToolCalls(ideSessionID)

	data, err := json.Marshal(converted)
	if err != nil {
		return "", err
	}
	return a.writeIDETranscriptCache(cwd, entireSessionID, ideSessionID, data)
}

