package kiro

import (
	"crypto/sha256"
	"encoding/hex"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"
)

// writeIDEV2Session creates ~/.kiro/sessions/<hash(repo)>/<id>/messages.jsonl
// with a fixed mtime, the layout newer Kiro IDE builds write.
func writeIDEV2Session(t *testing.T, home, repoRoot, sessionID, content string, mtime time.Time) string {
	t.Helper()
	sum := sha256.Sum256([]byte(filepath.Clean(repoRoot)))
	dir := filepath.Join(home, ".kiro", "sessions", hex.EncodeToString(sum[:])[:16], sessionID)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatalf("mkdir %s: %v", dir, err)
	}
	path := filepath.Join(dir, "messages.jsonl")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
	if err := os.Chtimes(path, mtime, mtime); err != nil {
		t.Fatalf("chtimes %s: %v", path, err)
	}
	return path
}

// v2Transcript is shaped like a real Kiro IDE messages.jsonl: metadata noise,
// a turn with interleaved text and tool calls, then a second turn.
const v2Transcript = `{"id":"1","timestamp":"2026-11-22T20:08:42.159Z","payload":{"type":"user","content":"rename the helper"}}
{"id":"2","timestamp":"2026-11-22T20:08:42.161Z","payload":{"type":"agent_note","content":"<session_context>ignored</session_context>"}}
{"id":"3","timestamp":"2026-11-22T20:08:42.171Z","payload":{"type":"turn_start","turnId":"t1"}}
{"id":"4","timestamp":"2026-11-22T20:08:44.458Z","payload":{"type":"session_metadata","key":"creditSplit","value":{}}}
{"id":"5","timestamp":"2026-11-22T20:08:46.504Z","payload":{"type":"assistant","content":"Reading the file first."}}
{"id":"6","timestamp":"2026-11-22T20:08:46.513Z","payload":{"type":"tool_call","toolCallId":"c1","toolName":"read_file","args":{"path":"src/a.ts"}}}
{"id":"7","timestamp":"2026-11-22T20:08:47.584Z","payload":{"type":"tool_result","toolCallId":"c1","content":"export const a = 1"}}
{"id":"8","timestamp":"2026-11-22T20:08:48.000Z","payload":{"type":"tool_call","toolCallId":"c2","toolName":"str_replace","args":{"path":"src/a.ts","oldStr":"a","newStr":"b"}}}
{"id":"9","timestamp":"2026-11-22T20:08:48.500Z","payload":{"type":"tool_call","toolCallId":"c3","toolName":"delete_file","args":{"targetFile":"src/old.ts"}}}
{"id":"10","timestamp":"2026-11-22T20:08:50.000Z","payload":{"type":"assistant","content":"Renamed."}}
{"id":"11","timestamp":"2026-11-22T20:08:53.556Z","payload":{"type":"turn_end","stopReason":"end_turn"}}
{"id":"12","timestamp":"2026-11-22T20:09:10.000Z","payload":{"type":"user","content":"now add a test"}}
{"id":"13","timestamp":"2026-11-22T20:09:12.000Z","payload":{"type":"tool_call","toolCallId":"c4","toolName":"fs_write","args":{"path":"src/a.test.ts","text":"..."}}}
`

func TestConvertIDEV2MessagesPreservesOrderAndPrompts(t *testing.T) {
	// The trailing partial line mimics Kiro appending while a hook runs.
	got, err := convertIDEV2Messages([]byte(v2Transcript + `{"id":"14","payload":{"type":"assis`))
	if err != nil {
		t.Fatalf("convertIDEV2Messages: %v", err)
	}

	type want struct {
		prompt   string
		response string
		tools    []string
	}
	expected := []want{
		{prompt: "rename the helper", response: "Reading the file first."},
		{tools: []string{"read_file", "str_replace", "delete_file"}},
		{response: "Renamed."},
		{prompt: "now add a test", tools: []string{"fs_write"}},
	}
	if len(got.History) != len(expected) {
		t.Fatalf("history entries = %d, want %d", len(got.History), len(expected))
	}
	for i, w := range expected {
		entry := got.History[i]
		if p := extractUserPrompt(entry.User.Content); p != w.prompt {
			t.Errorf("entry %d prompt = %q, want %q", i, p, w.prompt)
		}
		if w.response != "" && !strings.Contains(string(entry.Assistant), w.response) {
			t.Errorf("entry %d assistant = %s, want response %q", i, entry.Assistant, w.response)
		}
		for _, tool := range w.tools {
			if !strings.Contains(string(entry.Assistant), `"name":"`+tool+`"`) {
				t.Errorf("entry %d assistant = %s, want tool %q", i, entry.Assistant, tool)
			}
		}
	}
	if strings.Contains(string(got.History[0].User.Content), "session_context") {
		t.Error("agent_note leaked into the user prompt")
	}
}

func REDACTED(t *testing.T) {
	repoRoot := t.TempDir()
	home := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
	t.Setenv("HOME", home)
	t.Setenv("USER_PROMPT", "now add a test")

	writeIDEV2Session(t, home, repoRoot, "sess_older", `{"id":"1","payload":{"type":"user","content":"other chat"}}`+"\n",
		time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC))
	writeIDEV2Session(t, home, repoRoot, "sess_active", v2Transcript, time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC))

	agent := New()
	start, err := agent.ParseHook(HookNameUserPromptSubmit, nil)
	if err != nil {
		t.Fatalf("ParseHook(user-prompt-submit): %v", err)
	}
	if start == nil || start.SessionID != "sess_active" {
		t.Fatalf("prompt-submit session = %+v, want sess_active", start)
	}

	stop, err := agent.ParseHook(HookNameStop, nil)
	if err != nil {
		t.Fatalf("ParseHook(stop): %v", err)
	}
	if stop == nil || stop.SessionID != "sess_active" || stop.SessionRef == "" {
		t.Fatalf("stop event = %+v, want sess_active with a session ref", stop)
	}

	stored, err := os.ReadFile(stop.SessionRef)
	if err != nil {
		t.Fatalf("read cached transcript: %v", err)
	}
	if string(stored) == "{}" {
		t.Fatal("stop wrote the placeholder transcript, want the v2 chat")
	}
	if strings.Contains(string(stored), "other chat") {
		t.Fatal("cached transcript contains the inactive chat")
	}

	prompts, err := agent.ExtractPrompts(stop.SessionRef, 0)
	if err != nil {
		t.Fatalf("ExtractPrompts: %v", err)
	}
	if !slices.Equal(prompts, []string{"rename the helper", "now add a test"}) {
		t.Fatalf("prompts = %q", prompts)
	}

	files, _, err := agent.ExtractModifiedFiles(stop.SessionRef, 0)
	if err != nil {
		t.Fatalf("ExtractModifiedFiles: %v", err)
	}
	for _, want := range []string{"src/a.ts", "src/old.ts", "src/a.test.ts"} {
		if !slices.Contains(files, want) {
			t.Errorf("modified files = %q, missing %q", files, want)
		}
	}
	if slices.Contains(files, "src/a.ts") && slices.Index(files, "src/a.ts") != slices.LastIndex(files, "src/a.ts") {
		t.Errorf("modified files = %q, want no duplicates", files)
	}
}

func TestIDEV2MissingChatDoesNotFallBackToAnotherChat(t *testing.T) {
	repoRoot := t.TempDir()
	home := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
	t.Setenv("HOME", home)

	writeIDEV2Session(t, home, repoRoot, "sess_other", v2Transcript, time.Now())

	if _, err := New().ensureIDETranscript(repoRoot, "sess_gone", "sess_gone"); err == nil {
		t.Fatal("ensureIDETranscript succeeded for a missing v2 chat, want an error instead of another chat's transcript")
	}
}

func TestMostRecentlyActiveIDESessionPrefersNewerStore(t *testing.T) {
	repoRoot := t.TempDir()
	home := t.TempDir()
	t.Setenv("HOME", home)

	legacyDir := createIDEWorkspaceSessionsDir(t, home, repoRoot)
	writeIDESessionFile(t, legacyDir, "legacy-chat", `{"history":[]}`, time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC))
	writeIDEV2Session(t, home, repoRoot, "sess_new", v2Transcript, time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))

	got, err := mostRecentlyActiveIDESessionID(repoRoot)
	if err != nil || got != "sess_new" {
		t.Fatalf("mostRecentlyActiveIDESessionID = %q, %v; want sess_new", got, err)
	}

	// A legacy chat written after the v2 one still wins, so mixed installs
	// keep following whichever store Kiro is actually writing.
	writeIDESessionFile(t, legacyDir, "legacy-chat", `{"history":[]}`, time.Date(2026, 4, 1, 0, 0, 0, 0, time.UTC))
	got, err = mostRecentlyActiveIDESessionID(repoRoot)
	if err != nil || got != "legacy-chat" {
		t.Fatalf("mostRecentlyActiveIDESessionID = %q, %v; want legacy-chat", got, err)
	}
}

