	if stop == nil || stop.SessionID != "sess_active" || stop.SessionRef == "" {
		t.Fatalf("stop event = %+v, want sess_active with a session ref", stop)
	}

	stored, err := os.ReadFile(stop.SessionRef)
	if err != nil {
		t.Fatalf("read cached transcript: %v", err)
	}
	if string(stored) == "{}" {
		t.Fatal("stop wrote the placeholder transcript, want the v2 chat")
	}
	if strings.Contains(string(stored), "other chat") {
		t.Fatal("cached transcript contains the inactive chat")
	}

	prompts, err := agent.ExtractPrompts(stop.SessionRef, 0)
	if err != nil {
		t.Fatalf("ExtractPrompts: %v", err)
	}
	if !slices.Equal(prompts, []string{"rename the helper", "now add a test"}) {
		t.Fatalf("prompts = %q", prompts)
	}

	files, _, err := agent.ExtractModifiedFiles(stop.SessionRef, 0)
	if err != nil {
