package kiro

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
)

// Kiro IDE v2 hook files.
//
// Newer Kiro IDE builds load hooks from .kiro/hooks/*.json in this shape:
//
//	{"version":"v1","hooks":[{"name":…,"trigger":"Stop",
//	  "action":{"type":"command","command":"…"}}]}
//
// and pipe the event to the command as JSON on stdin, including session_id
// (the sess_<uuid> chat ID), hook_event_name, cwd and, for UserPromptSubmit,
// prompt. Those builds no longer run the legacy *.kiro.hook files directly;
// they offer to migrate each one to <name>.json and skip any whose target
// already exists.
//
// The v2 files therefore use exactly the migration target names. That keeps a
// later migration from producing a second copy of each Entire hook. Only the
// prompt-submit and stop hooks are enabled: the v2 transcript already records
// every tool call, so the tool-use hooks would only start a process per tool
// call. Their files are written disabled so the legacy tool-use hooks are not
// migrated into always-on hooks either.
//
// What breaks if this file is removed: on v2-only Kiro IDE builds, no Entire
// hook fires and no Kiro session is recorded.

type ideV2HookDef struct {
	Filename string
	Trigger  string
	CLIVerb  string
	Enabled  bool
}

var ideV2HookDefs = []ideV2HookDef{
	{Filename: "entire-prompt-submit", Trigger: "UserPromptSubmit", CLIVerb: HookNameUserPromptSubmit, Enabled: true},
	{Filename: "entire-stop", Trigger: "Stop", CLIVerb: HookNameStop, Enabled: true},
	{Filename: "entire-pre-tool-use", Trigger: "PreToolUse", CLIVerb: HookNamePreToolUse, Enabled: false},
	{Filename: "entire-post-tool-use", Trigger: "PostToolUse", CLIVerb: HookNamePostToolUse, Enabled: false},
}

const (
	ideV2HookFileSuffix    = ".json"
	ideV2HookSchemaVersion = "v1"
	ideV2HookTimeoutSecond = 30
)

type kiroV2HookFile struct {
	Version string          `json:"version"`
	Hooks   []kiroV2HookDoc `json:"hooks"`
}

type kiroV2HookDoc struct {
	Name        string           `json:"name"`
	Description string           `json:"description,omitempty"`
	Trigger     string           `json:"trigger"`
	Action      kiroV2HookAction `json:"action"`
	Timeout     int              `json:"timeout,omitempty"`
	Enabled     bool             `json:"enabled"`
}

type kiroV2HookAction struct {
	Type    string `json:"type"`
	Command string `json:"command"`
}

func ideV2HookPath(repoRoot string, def ideV2HookDef) string {
	return filepath.Join(repoRoot, ".kiro", ideHooksDir, def.Filename+ideV2HookFileSuffix)
}

func ideV2HookDoc(def ideV2HookDef, localDev bool) kiroV2HookFile {
	description := "Entire CLI " + def.Trigger + " hook"
	if !def.Enabled {
		description += " (disabled: the Kiro transcript already records tool calls; this file stops Kiro from migrating the legacy hook into an always-on copy)"
	}
	return kiroV2HookFile{
		Version: ideV2HookSchemaVersion,
		Hooks: []kiroV2HookDoc{{
			Name:        def.Filename,
			Description: description,
			Trigger:     def.Trigger,
			// v2 hooks receive the event on stdin, so no shell wrapper or
			// stdin redirect is needed.
			Action:  kiroV2HookAction{Type: "command", Command: hookCommandBase(localDev) + def.CLIVerb},
			Timeout: ideV2HookTimeoutSecond,
			Enabled: def.Enabled,
		}},
	}
}

func writeIDEV2Hooks(repoRoot string, localDev bool) error {
	if err := os.MkdirAll(filepath.Join(repoRoot, ".kiro", ideHooksDir), 0o700); err != nil {
		return err
	}
	for _, def := range ideV2HookDefs {
		data, err := marshalJSON(ideV2HookDoc(def, localDev))
		if err != nil {
			return err
		}
		if err := os.WriteFile(ideV2HookPath(repoRoot, def), data, 0o600); err != nil {
			return err
		}
	}
	return nil
}

func allIDEV2HooksPresent(repoRoot string, localDev bool) bool {
	for _, def := range ideV2HookDefs {
		data, err := os.ReadFile(ideV2HookPath(repoRoot, def))
		if err != nil {
			return false
		}
		var file kiroV2HookFile
		if err := json.Unmarshal(data, &file); err != nil || len(file.Hooks) != 1 {
			return false
		}
		want := ideV2HookDoc(def, localDev).Hooks[0]
		got := file.Hooks[0]
		if got.Trigger != want.Trigger || got.Action != want.Action || got.Enabled != want.Enabled {
			return false
		}
	}
	return true
}

func removeIDEV2Hooks(repoRoot string) error {
	for _, def := range ideV2HookDefs {
		if err := os.Remove(ideV2HookPath(repoRoot, def)); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
	}
	return nil
}

func enabledIDEV2HookCount() int {
	n := 0
	for _, def := range ideV2HookDefs {
		if def.Enabled {
			n++
		}
	}
	return n
}

