	}
	return false''','''	if _, err := os.Stat(filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.kiro.hook")); err == nil {
		return true
	}
	if _, err := os.Stat(filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.json")); err == nil {
		return true
	}
	return false'''),
('''			allIDEHooksPresent(repoRoot, localDev) {''','''			allIDEHooksPresent(repoRoot, localDev) &&
			allIDEV2HooksPresent(repoRoot, localDev) {'''),
]
for a,b in rep:
    assert s.count(a)==1, a[:70]; s=s.replace(a,b)
open(p,'w').write(s)
p='hooks_test.go'; s=open(p).read()
assert s.count('want %d", count, 9)')==2
