open(p,'w').write(s)
EOF
cat >> hooks_test.go <<'EOF'

func TestInstallHooksWritesV2HooksAtMigrationTargetNames(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	if _, err := New().InstallHooks(false, false); err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	enabled := map[string]bool{
		"entire-prompt-submit": true,
		"entire-stop":          true,
		"entire-pre-tool-use":  false,
		"entire-post-tool-use": false,
	}
	for name, wantEnabled := range enabled {
		// Kiro migrates <name>.kiro.hook to <name>.json and skips existing
		// targets, so the v2 file must sit at exactly that name.
		data, err := os.ReadFile(filepath.Join(repoRoot, ".kiro", "hooks", name+".json"))
		if err != nil {
			t.Fatalf("read v2 hook %s: %v", name, err)
		}
		var file kiroV2HookFile
		if err := json.Unmarshal(data, &file); err != nil {
			t.Fatalf("unmarshal v2 hook %s: %v", name, err)
		}
		if file.Version != "v1" || len(file.Hooks) != 1 {
			t.Fatalf("v2 hook %s = %s, want version v1 with one hook", name, data)
		}
		hook := file.Hooks[0]
		if hook.Enabled != wantEnabled {
			t.Errorf("v2 hook %s enabled = %v, want %v", name, hook.Enabled, wantEnabled)
		}
		if hook.Action.Type != "command" || !strings.HasPrefix(hook.Action.Command, "entire hooks kiro ") {
			t.Errorf("v2 hook %s action = %+v, want a bare entire hooks command", name, hook.Action)
		}
		if strings.Contains(hook.Action.Command, "sh -c") {
			t.Errorf("v2 hook %s must not wrap stdin: Kiro passes the event on stdin", name)
		}
	}

	if !New().AreHooksInstalled() {
		t.Fatal("AreHooksInstalled() = false after install")
	}
	if err := os.Remove(filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.json")); err != nil {
		t.Fatal(err)
	}
	// A missing v2 hook must make a non-forced install repair it.
	count, err := New().InstallHooks(false, false)
	if err != nil || count == 0 {
		t.Fatalf("InstallHooks() after removing a v2 hook = %d, %v; want a reinstall", count, err)
	}

	if err := New().UninstallHooks(); err != nil {
		t.Fatalf("UninstallHooks() error = %v", err)
	}
	for name := range enabled {
		if _, err := os.Stat(filepath.Join(repoRoot, ".kiro", "hooks", name+".json")); !os.IsNotExist(err) {
			t.Errorf("v2 hook %s should be removed, got err=%v", name, err)
		}
	}
}

func TestParseHookStopUsesV2PayloadSessionID(t *testing.T) {
	repoRoot := t.TempDir()
	home := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
	t.Setenv("HOME", home)

	writeIDEV2Session(t, home, repoRoot, "sess_named", v2Transcript, time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC))
	// A newer chat exists, but the payload names the one that fired.
	writeIDEV2Session(t, home, repoRoot, "sess_newer", `{"id":"1","payload":{"type":"user","content":"x"}}`+"\n", time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))

	payload := `{"session_id":"sess_named","hook_event_name":"Stop","cwd":"` + repoRoot + `"}`
	event, err := New().ParseHook(HookNameStop, []byte(payload))
	if err != nil {
		t.Fatalf("ParseHook(stop) error = %v", err)
	}
	if event == nil || event.SessionID != "sess_named" {
		t.Fatalf("stop event = %+v, want sess_named from the payload", event)
	}
	data, err := os.ReadFile(event.SessionRef)
	if err != nil {
		t.Fatalf("read cached transcript: %v", err)
	}
	if !strings.Contains(string(data), "rename the helper") {
		t.Fatalf("cached transcript lacks the named chat: %.200s", data)
	}
}
EOF
