// ideV2HookCommand builds the command a v2 hook runs.
//
// Kiro IDE runs hooks with the IDE's own PATH, which can differ from a login
// shell's. When it reaches `entire` (for example through a symlink) but not
// this binary's directory, Entire cannot discover the external agent and
// fails with `unknown agent "kiro"`. Prefixing PATH with the directory this
// binary was installed in makes discovery independent of Kiro's PATH.
func ideV2HookCommand(localDev bool, verb string) string {
	base := hookCommandBase(localDev) + verb
	if localDev || runtimeGOOS == osWindows {
		return base
	}
	dir := agentBinaryDir()
	if dir == "" {
		return base
	}
	return "PATH=" + shellSingleQuote(dir) + `:"$PATH" ` + base
}

// agentBinaryDir returns the directory of the running entire-agent-kiro
// binary, or "" when it cannot be determined or is a temporary build.
var agentBinaryDir = func() string {
	exe, err := os.Executable()
	if err != nil {
		return ""
	}
	if resolved, err := filepath.EvalSymlinks(exe); err == nil {
		exe = resolved
	}
	dir := filepath.Dir(exe)
	// `go run` and `go test` binaries live in a temporary build directory
	// that disappears; baking that into a hook would break it.
	if strings.HasPrefix(dir, os.TempDir()) || strings.Contains(dir, string(filepath.Separator)+"go-build") {
		return ""
	}
	return dir
}

// shellSingleQuote quotes s for POSIX sh.
func shellSingleQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
}
